// Asignar inbox rotativo basado en hash del email
const lead = $input.first().json;
const email = lead.properties.email.email || '';
const hash = [...email].reduce((a, c) => a + c.charCodeAt(0), 0);
const inboxes = [
  { from: 'pablo@get-marli.com', from_name: 'Pablo (Marli)', cred: 'smtp-cold-pablo' },
  { from: 'maria@get-marli.com', from_name: 'María (Marli)', cred: 'smtp-cold-maria' },
  { from: 'david@get-marli.com', from_name: 'David (Marli)', cred: 'smtp-cold-david' },
  { from: 'laura@marli-team.es', from_name: 'Laura (Marli)', cred: 'smtp-cold-laura' },
  { from: 'carlos@marli-team.es', from_name: 'Carlos (Marli)', cred: 'smtp-cold-carlos' }
];
const inbox = inboxes[hash % inboxes.length];

// Determinar qué email de la secuencia mandar
const secuencia = lead.properties.secuencia.select.name || 'tripwire';
const paso = lead.properties.paso_secuencia.number || 1;

// Variables para merge tags
const nombre_propio = (lead.properties.nombre.title?.[0]?.text?.content || 'compañero/a').split(' ')[0];
const opt_out_url = `${$env.OPT_OUT_BASE_URL}?id=${lead.id}`;

return [{
  json: {
    lead_id: lead.id,
    email: email,
    nombre: lead.properties.nombre.title?.[0]?.text?.content,
    nombre_propio,
    ciudad: lead.properties.ciudad.rich_text?.[0]?.text?.content || '',
    inbox,
    secuencia,
    paso,
    opt_out_url
  }
}];

// Construir el contenido del email según secuencia + paso
const { secuencia, paso, nombre_propio, ciudad, opt_out_url } = $input.first().json;
const tripwire = $env.TRIPWIRE_LANDING_URL || 'https://marli.agency/crm-gratis';

const plantillas = {
  tripwire: {
    1: {
      subject: `${nombre_propio}, una pregunta rápida sobre tu consulta`,
      body_html: `<p>Hola ${nombre_propio},</p>
<p>Vi tu perfil en Doctoralia/COP y soy psicólogo... me imagino que como yo, dedicas demasiado tiempo a redactar informes en Word, programar sesiones a mano y perseguir cobros.</p>
<p>Llevo meses construyendo una herramienta que me ahorra ~8h/semana en eso (CRM + plantillas de informes + chatbot de citas).</p>
<p>Hoy doy gratis la plantilla básica de CRM en Notion con 5 plantillas de informes ya redactadas. Sin email-trampa, sin tarjeta. Si te sirve, te sirve.</p>
<p><a href="${tripwire}">Aquí la tienes →</a></p>
<p>Un abrazo,<br>Pablo</p>
<p style="font-size:11px;color:#888;border-top:1px solid #eee;padding-top:8px">Te escribo porque tu email aparece en tu web profesional / perfil COP. Si prefieres no recibir más mensajes, <a href="${opt_out_url}">dilo aquí</a> y eliminaré tu dato. Encontrarás más info en nuestra política de privacidad.</p>`
    },
    2: {
      subject: `Re: ${nombre_propio}, una pregunta rápida sobre tu consulta`,
      body_html: `<p>${nombre_propio},</p>
<p>Cuelo el link otra vez por si el primero quedó perdido.</p>
<p><a href="${tripwire}">Plantilla CRM Notion + 5 informes Word listos</a> — gratis, sin tarjeta.</p>
<p>Si no te sirve, dímelo y te dejo en paz.</p>
<p>Pablo</p>
<p style="font-size:11px;color:#888"><a href="${opt_out_url}">No recibir más</a></p>`
    },
    3: {
      subject: `Una historia de Mar (psicóloga en Valencia) — y cómo recuperó 8h/semana`,
      body_html: `<p>Hola ${nombre_propio},</p>
<p>Mar tenía la consulta llena de post-its y un Excel que se le rompía cada lunes. En 3 horas pasó todo a Notion + Word con plantillas y ahora redacta un informe en 25 min en lugar de 2h.</p>
<p>Le dejé el sistema gratis. Le sirvió. Aquí lo tienes tú también:</p>
<p><a href="${tripwire}">Descargar plantilla Marli</a></p>
<p>Pablo</p>
<p style="font-size:11px;color:#888"><a href="${opt_out_url}">No me escribas más</a></p>`
    },
    4: {
      subject: `Última vez (de verdad), ${nombre_propio}`,
      body_html: `<p>${nombre_propio}, este es mi 4º email — el último.</p>
<p>Si no te interesa la plantilla CRM gratis, no pasa nada, te elimino de la lista (o haz clic abajo si quieres).</p>
<p>Pero si llegaste a abrir alguno de los anteriores y se te ha pasado, <a href="${tripwire}">aquí está</a>. Te ahorra horas semanales y es literalmente gratis.</p>
<p>Cuídate,<br>Pablo</p>
<p style="font-size:11px;color:#888"><a href="${opt_out_url}">Borrarme de la lista</a></p>`
    },
    5: {
      subject: `${nombre_propio}, ¿te puedo hacer 1 favor?`,
      body_html: `<p>Hola ${nombre_propio},</p>
<p>Si me has ignorado los 4 emails anteriores, lo entiendo, soy un desconocido. Pero antes de borrarte de la lista, me ayudaría mucho saber por qué no te interesó.</p>
<p>¿Es porque ya tienes una herramienta? ¿Porque desconfías? ¿Porque no ves el problema? Cualquier respuesta de 1 línea me sirve.</p>
<p>Si me dices algo, perfecto. Si no, no te escribo más.</p>
<p>Gracias,<br>Pablo</p>
<p style="font-size:11px;color:#888"><a href="${opt_out_url}">Borrarme</a></p>`
        }
      }
};

const plantilla = plantillas[secuencia]?.[paso];
if (!plantilla) {
  throw new Error(`Plantilla no encontrada: ${secuencia}/${paso}`);
}

return [{ json: { ...$input.first().json, ...plantilla } }];
